namespace sv_e34c7191879a464e8c5085c923e04e39.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse and alert count.
/// In Blazor Server, scoped lifetime = per circuit = per user session,
/// so each manager gets independent state.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";
    private int _lowStockCount;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount == value) return;
            _lowStockCount = value;
            NotifyStateChanged();
        }
    }

    /// <summary>
    /// Event that all subscribed components listen to for state changes.
    /// Enables cross-component communication without parent-child relationships.
    /// </summary>
    public event Func<Task>? OnChange;

    private void NotifyStateChanged()
    {
        if (OnChange is not null)
        {
            // Fire-and-forget to all subscribers
            _ = OnChange.Invoke();
        }
    }

    public void Dispose()
    {
        OnChange = null;
    }
}

namespace sv_e34c7191879a464e8c5085c923e04e39.Services;

/// <summary>
/// Simulates checking inventory levels for a given warehouse.
/// Returns a random low-stock count to mimic a real database query.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database call
        int count = _random.Next(0, 16); // 0–15 inclusive
        return Task.FromResult(count);
    }
}

namespace sv_e34c7191879a464e8c5085c923e04e39.Services;

/// <summary>
/// Manages the 10-second polling timer for low-stock alerts.
/// Starts/stops polling on demand and pushes new counts into WarehouseStateService,
/// which then notifies all subscribed components.
/// </summary>
public sealed class InventoryPollingService : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseStateService _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public InventoryPollingService(
        InventoryAlertService alertService,
        WarehouseStateService warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;
    }

    /// <summary>
    /// Increment subscriber count and start polling if not already running.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Decrement subscriber count and stop polling when no subscribers remain.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopPolling();
        }
    }

    /// <summary>
    /// Force an immediate poll (e.g., when warehouse changes).
    /// </summary>
    public async Task PollNowAsync()
    {
        var count = await _alertService.GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _warehouseState.LowStockCount = count;
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
        _timer = null;
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Immediate first poll
        await PollNowAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (!await _timer!.WaitForNextTickAsync(ct))
                    break;

                await PollNowAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        StopPolling();
    }
}

