@using sv_e34c7191879a464e8c5085c923e04e39.Services
@inject WarehouseStateService WarehouseState
@inject InventoryPollingService PollingService
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect" class="form-select form-select-sm d-inline-block w-auto"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        <option value="WH-001">Warehouse A (WH-001)</option>
        <option value="WH-002">Warehouse B (WH-002)</option>
        <option value="WH-003">Warehouse C (WH-003)</option>
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
        // Immediately poll for the new warehouse's alerts
        await PollingService.PollNowAsync();
    }

    private Task HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

