@page "/dashboard"
@using sv_e34c7191879a464e8c5085c923e04e39.Services
@inject WarehouseStateService WarehouseState
@inject InventoryPollingService PollingService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @AlertCardClass">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 fw-bold">@WarehouseState.LowStockCount</p>
                <p class="card-text text-muted">
                    Items below minimum level &bull; Refreshes every 10s
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
